import fs from 'node:fs';
import crypto from 'node:crypto';
const raw=fs.readFileSync('operations/cold-cycle.json','utf8');
const obj=JSON.parse(raw);
const digest=s=>crypto.createHash('sha256').update(s).digest('hex');
console.log('file sha256',digest(raw));
console.log('minified sha256',digest(JSON.stringify(obj)));
console.log('samples only',digest(JSON.stringify(obj.samples)));
